import React from 'react';
import { Navbar, Container, Button, Dropdown, Brand } from 'react-bootstrap';
import Avatar from 'react-avatar';

function Header({ username, onLogout }) {
    return (
        <Navbar bg="dark" variant="dark" className="py-3">
        <Container fluid>
            {/* App Name / Logo */}
            <Brand className='me-auto'>
            Chat App
            </Brand>
            <Navbar.Brand href="/" className="me-auto">
            Chat App
            </Navbar.Brand>

            {/* User Dropdown */}
            <div className="d-flex align-items-center">
            <Dropdown align="end">
                <Dropdown.Toggle variant="dark" id="user-dropdown" className="rounded p-2">
                <Avatar
                    name={username}
                    size="32"
                    maxInitials='2'
                    round={true}
                    color="#007bff"     // Background color
                    fgColor="#fff"      // Text color
                    className="me-2"
                />
                <span className="fw-bold">{username}</span>
                </Dropdown.Toggle>

                <Dropdown.Menu>
                <Dropdown.Item onClick={onLogout} className="text-danger">
                    Logout
                </Dropdown.Item>
                </Dropdown.Menu>
            </Dropdown>
            </div>
        </Container>
        </Navbar>
    );
}

export default Header;
